import { readFileSync } from "node:fs";
import { join } from "node:path";

const LOCALES = [
	"ja",
	"zh-CN",
	"fr",
	"ko",
	"zh-TW",
	"es",
	"de",
	"pt-BR",
	"it",
	"ru",
	"tr",
	"pl",
	"nl",
	"id",
	"cs",
	"vi",
];

function catalog(locale: string): Map<string, string> {
	const src = readFileSync(
		join("packages/i18n/locales", locale, "messages.po"),
		"utf8",
	).replace(/\r\n/g, "\n");
	const out = new Map<string, string>();
	const lines = src.split("\n");
	for (let i = 0; i < lines.length; i++) {
		const line = lines[i] ?? "";
		if (!line.startsWith('msgid "')) continue;
		const id = line.slice(7, -1);
		const next = lines[i + 1] ?? "";
		if (!next.startsWith('msgstr "')) continue;
		out.set(id, next.slice(8, -1));
	}
	return out;
}

const ids = process.argv.slice(2);
const cats = new Map(LOCALES.map((l) => [l, catalog(l)]));
for (const id of ids) {
	console.log(`\n### ${id}`);
	for (const l of LOCALES) {
		console.log(`${l}\t${cats.get(l)?.get(id) ?? "<MISSING>"}`);
	}
}

