#!/usr/bin/env node

/**
 * (I18N-ID-GATE) Blocks the class of bug where a translated string renders as
 * its own message id in the packaged app.
 *
 * Lingui's babel macro strips the inline fallback text from a production
 * build, so a call site carrying an explicit `id:` that never made it into
 * `packages/i18n/locales/en/messages.po` renders the raw id — that is how the
 * sidebar shipped the literal text `dashboard.sidebar.header.kanban` instead
 * of "Kanban". Upstream's own CI catches this by re-running
 * `lingui extract` + `compile --strict` and failing on a dirty catalog diff;
 * this fork drops every upstream workflow ((WORKFLOW-FORK-OWNED)), so nothing
 * caught it here.
 *
 * The invariant asserted is narrower than upstream's and far cheaper: every
 * explicit lingui message id present in the source must exist in the English
 * catalog. Text-as-id call sites (`<Trans>Kanban</Trans>`, `t({ message })`),
 * which are the convention this repo now follows, are not checked at all —
 * they degrade to readable English rather than to a raw token, so a missed
 * extract is a translation gap, not a visible defect.
 *
 * Deliberately NOT a full extract: running babel over every source root on the
 * Windows ARM64 runner costs minutes, and once a catalog diff is a build gate
 * (BUILD-REPAIR) can satisfy it by inventing unreviewed translations.
 */

import fs from "node:fs";
import path from "node:path";

const repoRoot = process.cwd();
if (!fs.existsSync(path.join(repoRoot, "package.json"))) {
	console.error(
		"(I18N-ID-GATE) run from the repository root; package.json is missing",
	);
	process.exit(1);
}

const CATALOG = "packages/i18n/locales/en/messages.po";

// Mirrors the `include` list in packages/i18n/lingui.config.ts: the gate must
// see exactly what extraction sees, or it passes a call site the catalog will
// never learn about.
const SOURCE_ROOTS = [
	"apps/desktop/src",
	"apps/web/src",
	"apps/marketing/src",
	"apps/admin/src",
	"apps/docs/src",
	"apps/mobile/app",
	"apps/mobile/screens",
	"apps/mobile/components",
	"apps/mobile/hooks",
	"apps/mobile/lib",
	"packages/ui/src",
	"packages/chat-ui/src",
	"packages/shared/src",
	"packages/i18n/src",
];
const SOURCE_EXTENSIONS = new Set([".ts", ".tsx"]);

// Same exclusions lingui applies, so the gate cannot demand a catalog entry
// for a string extraction never collects.
function isExcluded(relative) {
	return (
		relative.includes("/node_modules/") ||
		/\.(?:test|stories)\.[^/]+$/.test(relative)
	);
}

// `<Trans id="literal">` and a literal `id:` key inside a lingui descriptor
// (`t({ id: "..." })`, `msg({ id: "..." })`, `defineMessage({ id: "..." })`,
// `i18n._({ id: "..." })`). Computed ids (`id={someVar}`) are invisible to
// extraction too, so they are out of scope rather than silently tolerated.
const TRANS_ID = /<Trans\b[^>]*?\sid="([^"]+)"/g;
const DESCRIPTOR_ID =
	/\b(?:t|msg|defineMessage|i18n\._)\(\{\s*id:\s*"([^"]+)"/g;

function relativePath(absolute) {
	return path.relative(repoRoot, absolute).split(path.sep).join("/");
}

function listFiles(root) {
	if (!fs.existsSync(root)) return [];
	const files = [];
	for (const entry of fs.readdirSync(root, { withFileTypes: true })) {
		const absolute = path.join(root, entry.name);
		if (entry.isDirectory()) {
			if (entry.name === "node_modules" || entry.name === ".cache") continue;
			files.push(...listFiles(absolute));
		} else if (SOURCE_EXTENSIONS.has(path.extname(entry.name))) {
			files.push(absolute);
		}
	}
	return files;
}

function readCatalogIds() {
	const catalogPath = path.join(repoRoot, CATALOG);
	if (!fs.existsSync(catalogPath)) {
		console.error(`(I18N-ID-GATE) missing English catalog at ${CATALOG}`);
		process.exit(1);
	}
	const ids = new Set();
	for (const line of fs.readFileSync(catalogPath, "utf8").split(/\r?\n/)) {
		const match = /^msgid "(.*)"$/.exec(line);
		if (match) ids.add(match[1]);
	}
	return ids;
}

function lineOf(source, index) {
	return source.slice(0, index).split("\n").length;
}

const catalogIds = readCatalogIds();
const failures = [];

for (const root of SOURCE_ROOTS) {
	for (const absolute of listFiles(path.join(repoRoot, root))) {
		const relative = relativePath(absolute);
		if (isExcluded(relative)) continue;
		const source = fs.readFileSync(absolute, "utf8");
		for (const pattern of [TRANS_ID, DESCRIPTOR_ID]) {
			pattern.lastIndex = 0;
			let match = pattern.exec(source);
			while (match !== null) {
				const id = match[1];
				if (!catalogIds.has(id)) {
					failures.push(
						`${relative}:${lineOf(source, match.index)}: "${id}" is not in ${CATALOG}`,
					);
				}
				match = pattern.exec(source);
			}
		}
	}
}

if (failures.length > 0) {
	console.error(
		"(I18N-ID-GATE) explicit lingui message ids with no English catalog entry —",
	);
	console.error(
		"these render as the raw id in a production build. Either drop the explicit",
	);
	console.error(
		'id and let the source text be the id (<Trans>Text</Trans>, t({ message })),',
	);
	console.error(
		"or run `bun run check:i18n` and commit the catalogs with the translations.",
	);
	for (const failure of [...new Set(failures)].sort()) {
		console.error(`- ${failure}`);
	}
	process.exit(1);
}

console.log(
	`(I18N-ID-GATE) every explicit lingui id resolves in ${CATALOG} (${catalogIds.size} entries)`,
);

