/**
 * Applies the review findings to the catalogs:
 *  - fills the new `countdown`-context "now" entry (the shared entry carries
 *    past-tense "just now" in fr/ko/vi/zh, wrong for a countdown at zero),
 *  - takes the sibling-consistency and idiom corrections raised on the nine
 *    strings added by this change.
 *
 * Every edit names the exact value it expects to replace, so a catalog that
 * has moved on fails loudly instead of being silently overwritten.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const DIR = "packages/i18n/locales";

/** msgctxt "countdown" / msgid "now" — currently empty in every locale. */
const COUNTDOWN_NOW: Record<string, string> = {
	ja: "今",
	"zh-CN": "现在",
	fr: "maintenant",
	ko: "지금",
	"zh-TW": "現在",
	es: "ahora",
	de: "jetzt",
	"pt-BR": "agora",
	it: "adesso",
	ru: "сейчас",
	tr: "şimdi",
	pl: "teraz",
	nl: "nu",
	id: "sekarang",
	cs: "teď",
	vi: "bây giờ",
};

/** locale -> msgid -> [expected current value, corrected value] */
const CORRECTIONS: Record<string, Record<string, [string, string]>> = {
	de: {
		"Terminal session did not close": [
			"Terminalsitzung wurde nicht geschlossen",
			"Terminal-Sitzung wurde nicht geschlossen",
		],
		"Failed to open releases page: {message}": [
			"Releases-Seite konnte nicht geöffnet werden: {message}",
			"Versionsseite konnte nicht geöffnet werden: {message}",
		],
	},
	"pt-BR": {
		"Terminal session did not close": [
			"A sessão do terminal não foi encerrada",
			"A sessão de terminal não foi encerrada",
		],
		"Runs in {masterLabel}": [
			"Executa em {masterLabel}",
			"Roda em {masterLabel}",
		],
		"Failed to open releases page: {message}": [
			"Falha ao abrir a página de versões: {message}",
			"Falha ao abrir a página de versões: {message}",
		],
	},
	it: {
		"Runs in {masterLabel}": [
			"Esegue in {masterLabel}",
			"In esecuzione in {masterLabel}",
		],
		"Failed to open releases page: {message}": [
			"Apertura della pagina delle release non riuscita: {message}",
			"Apertura della pagina delle versioni non riuscita: {message}",
		],
	},
	ja: {
		"Runs in {masterLabel}": ["{masterLabel} で実行", "{masterLabel}で実行"],
	},
	"zh-CN": {
		"Runs in {masterLabel}": [
			"在 {masterLabel} 中运行",
			"在{masterLabel}中运行",
		],
		"Failed to open releases page: {message}": [
			"打开发布页面失败：{message}",
			"打开版本页面失败：{message}",
		],
	},
	"zh-TW": {
		"Runs in {masterLabel}": [
			"在 {masterLabel} 中執行",
			"在{masterLabel}中執行",
		],
		"Failed to open releases page: {message}": [
			"開啟發布頁面失敗：{message}",
			"開啟版本頁面失敗：{message}",
		],
	},
	cs: {
		"The host will keep retrying.": [
			"Host to bude zkoušet dál.",
			"Host se bude dál pokoušet.",
		],
		"Failed to open releases page: {message}": [
			"Nepodařilo se otevřít stránku vydání: {message}",
			"Nepodařilo se otevřít stránku verzí: {message}",
		],
	},
	nl: {
		"Failed to open releases page: {message}": [
			"Openen van releasespagina mislukt: {message}",
			"Openen van versiepagina mislukt: {message}",
		],
	},
	pl: {
		"Failed to open releases page: {message}": [
			"Nie udało się otworzyć strony wydań: {message}",
			"Nie udało się otworzyć strony wersji: {message}",
		],
	},
	ru: {
		"Failed to open releases page: {message}": [
			"Не удалось открыть страницу релизов: {message}",
			"Не удалось открыть страницу версий: {message}",
		],
	},
};

const LOCALES = [
	"ja",
	"zh-CN",
	"fr",
	"ko",
	"zh-TW",
	"es",
	"de",
	"pt-BR",
	"it",
	"ru",
	"tr",
	"pl",
	"nl",
	"id",
	"cs",
	"vi",
];

type Plan = { path: string; lines: string[]; eol: string; edits: number };

function plan(locale: string): Plan {
	const path = join(DIR, locale, "messages.po");
	const raw = readFileSync(path, "utf8");
	const eol = raw.includes("\r\n") ? "\r\n" : "\n";
	const lines = raw.replace(/\r\n/g, "\n").split("\n");
	const corrections = CORRECTIONS[locale] ?? {};
	const pending = new Set(Object.keys(corrections));
	let countdownFilled = false;
	let edits = 0;

	for (let i = 0; i < lines.length; i++) {
		const line = lines[i] ?? "";
		if (!line.startsWith('msgid "')) continue;
		const id = line.slice(7, -1);
		const context = (lines[i - 1] ?? "").startsWith('msgctxt "')
			? (lines[i - 1] ?? "").slice(9, -1)
			: null;
		const current = lines[i + 1] ?? "";
		if (!current.startsWith('msgstr "')) continue;
		const value = current.slice(8, -1);

		if (id === "now" && context === "countdown") {
			const translation = COUNTDOWN_NOW[locale];
			if (translation === undefined) {
				throw new Error(`${locale}: no countdown "now" translation`);
			}
			if (value !== "") {
				throw new Error(`${locale}: countdown "now" already set to "${value}"`);
			}
			lines[i + 1] = `msgstr "${translation}"`;
			countdownFilled = true;
			edits++;
			continue;
		}

		if (context !== null) continue;
		const correction = corrections[id];
		if (correction === undefined) continue;
		const [expected, corrected] = correction;
		if (value !== expected) {
			throw new Error(
				`${locale} / "${id}": expected "${expected}", found "${value}"`,
			);
		}
		pending.delete(id);
		if (corrected !== expected) {
			lines[i + 1] = `msgstr "${corrected}"`;
			edits++;
		}
	}

	if (!countdownFilled) throw new Error(`${locale}: countdown "now" not found`);
	if (pending.size > 0) {
		throw new Error(`${locale}: msgids not found: ${[...pending].join(", ")}`);
	}
	return { path, lines, eol, edits };
}

const plans = LOCALES.map(plan);
for (const p of plans) {
	writeFileSync(p.path, p.lines.join(p.eol), "utf8");
	console.log(`${p.path}: ${p.edits}`);
}

