const LOCALES = [
	"ja",
	"zh-CN",
	"fr",
	"ko",
	"zh-TW",
	"es",
	"de",
	"pt-BR",
	"it",
	"ru",
	"tr",
	"pl",
	"nl",
	"id",
	"cs",
	"vi",
];

type Plan = { path: string; lines: string[]; eol: string; edits: number };

function plan(locale: string): Plan {
	const path = join(DIR, locale, "messages.po");
	const raw = readFileSync(path, "utf8");
	const eol = raw.includes("\r\n") ? "\r\n" : "\n";
	const lines = raw.replace(/\r\n/g, "\n").split("\n");
	const corrections = CORRECTIONS[locale] ?? {};
	const pending = new Set(Object.keys(corrections));
	let countdownFilled = false;
	let edits = 0;

	for (let i = 0; i < lines.length; i++) {
		const line = lines[i] ?? "";
		if (!line.startsWith('msgid "')) continue;
		const id = line.slice(7, -1);
		const context = (lines[i - 1] ?? "").startsWith('msgctxt "')
			? (lines[i - 1] ?? "").slice(9, -1)
			: null;
		const current = lines[i + 1] ?? "";
		if (!current.startsWith('msgstr "')) continue;
		const value = current.slice(8, -1);

		if (id === "now" && context === "countdown") {
			const translation = COUNTDOWN_NOW[locale];
			if (translation === undefined) {
				throw new Error(`${locale}: no countdown "now" translation`);
			}
			if (value !== "") {
				throw new Error(`${locale}: countdown "now" already set to "${value}"`);
			}
			lines[i + 1] = `msgstr "${translation}"`;
			countdownFilled = true;
			edits++;
			continue;
		}

		if (context !== null) continue;
		const correction = corrections[id];
		if (correction === undefined) continue;
		const [expected, corrected] = correction;
		if (value !== expected) {
			throw new Error(
				`${locale} / "${id}": expected "${expected}", found "${value}"`,
			);
		}
		pending.delete(id);
		if (corrected !== expected) {
			lines[i + 1] = `msgstr "${corrected}"`;
			edits++;
		}
	}

	if (!countdownFilled) throw new Error(`${locale}: countdown "now" not found`);
	if (pending.size > 0) {
		throw new Error(`${locale}: msgids not found: ${[...pending].join(", ")}`);
	}
	return { path, lines, eol, edits };
}

const plans = LOCALES.map(plan);
for (const p of plans) {
	writeFileSync(p.path, p.lines.join(p.eol), "utf8");
	console.log(`${p.path}: ${p.edits}`);
}
